CREATE COLUMN TABLE "TEST_AP"."FAC2" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "DprArea" NVARCHAR(15) NOT NULL , "PeriodCat" NVARCHAR(10) NOT NULL , "VisOrder" INTEGER CS_INT NOT NULL , "OldDprSt" NVARCHAR(1) DEFAULT 'Y', "NewDprSt" NVARCHAR(1) DEFAULT 'Y', "OldFactor" DECIMAL(21,6) CS_FIXED, "NewFactor" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("AbsEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "FAC2_PERCONTROL" ON "TEST_AP"."FAC2" ( "AbsEntry" ASC, "DprArea" ASC, "PeriodCat" ASC, "VisOrder" ASC )